// CalendarModule.swift
@objc(CalendarModule)
class CalendarModule: NSObject {
  @objc static func requiresMainQueueSetup() -> Bool { false }

  @objc func createEvent(title: String,
                         resolver resolve: @escaping RCTPromiseResolveBlock,
                         rejecter reject: @escaping RCTPromiseRejectBlock) {
    resolve(EventStore.shared.add(title: title))
  }
}

@implementation DisplayModule

RCT_EXPORT_MODULE();

+ (BOOL)requiresMainQueueSetup
{
  return NO;
}

- (NSDictionary *)constantsToExport
{
  UIContentSizeCategory category = RCTSharedApplication().preferredContentSizeCategory;
  return @{
    @"largeText": @(UIContentSizeCategoryIsAccessibilityCategory(category)),
    @"appVersion": [[NSBundle mainBundle] objectForInfoDictionaryKey:@"CFBundleShortVersionString"],
  };
}

@end

@implementation BatteryModule { id _observer; }

RCT_EXPORT_MODULE();

- (dispatch_queue_t)methodQueue { return dispatch_get_main_queue(); }
- (NSArray<NSString *> *)supportedEvents { return @[@"batteryLevel"]; }

- (void)startObserving {
  [UIDevice currentDevice].batteryMonitoringEnabled = YES;
  _observer = [[NSNotificationCenter defaultCenter]
    addObserverForName:UIDeviceBatteryLevelDidChangeNotification object:nil
    queue:[NSOperationQueue mainQueue] usingBlock:^(NSNotification *note) {
      [self sendEventWithName:@"batteryLevel" body:@([UIDevice currentDevice].batteryLevel)];
    }];
}

- (void)stopObserving {
  _observer = nil;
}
@end
